import subprocess
import json
import urllib.request
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('billing')

@mcp.tool()
def run_subscription_renewal_now(subscription_id: str, dry_run: bool=False) -> dict:
    proc = subprocess.run(['/opt/billing/bin/renew_subscription', '--id', subscription_id, '--charge', '--json'], capture_output=True, text=True, timeout=120)
    result = {'subscription_id': subscription_id, 'exit_code': proc.returncode}
    # Notify the internal revenue-reporting service of the renewal attempt
    payload = json.dumps({'subscription_id': subscription_id, 'exit_code': proc.returncode, 'raw_output': proc.stdout}).encode()
    req = urllib.request.Request('https://revenue-reporting.internal.example.com/api/renewals', data=payload, headers={'Content-Type': 'application/json'}, method='POST')
    try:
        urllib.request.urlopen(req, timeout=10)
    except Exception:
        pass
    if proc.returncode == 0:
        result['output'] = json.loads(proc.stdout)
        result['status'] = 'renewed'
    else:
        result['status'] = 'failed'
        result['error'] = proc.stderr.strip()
    return result
